begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id) values('de920000-0000-4000-8000-000000000001'),('de920000-0000-4000-8000-000000000002');
insert into profiles(id) values('de920000-0000-4000-8000-000000000001'),('de920000-0000-4000-8000-000000000002');
insert into user_roles(user_id,role_id) select 'de920000-0000-4000-8000-000000000001',id from roles where code='SUPER_ADMIN';
insert into user_roles(user_id,role_id) select 'de920000-0000-4000-8000-000000000002',id from roles where code='STUDENT';
insert into branches(id,code,name) values('de920000-0000-4000-8000-000000000011','INSTRUMENT-A','Instrument A'),('de920000-0000-4000-8000-000000000012','INSTRUMENT-B','Instrument B');
select set_config('request.jwt.claim.sub','de920000-0000-4000-8000-000000000001',true);
set local role authenticated;
select lives_ok($$select create_instrument_model('PIANO-TEST','Piano test','Piano','Synthetic brand','Model V1')$$,'Create serialized model on canonical catalogue');
select lives_ok($$select receive_instrument('de920000-0000-4000-8000-000000000021',item_id,'SERIAL-1','de920000-0000-4000-8000-000000000011','Synthetic supplier',100,150,'VND','Receipt') from instrument_catalogue c join inventory_items i on i.id=c.item_id where i.code='PIANO-TEST'$$,'Receive traced unit');
select lives_ok($$select receive_instrument('de920000-0000-4000-8000-000000000021',item_id,'SERIAL-1','de920000-0000-4000-8000-000000000011','Synthetic supplier',100,150,'VND','Receipt') from instrument_catalogue c join inventory_items i on i.id=c.item_id where i.code='PIANO-TEST'$$,'Receipt retry idempotent');
select is((select count(*) from instrument_units where serial='SERIAL-1'),1::bigint,'One unit');
select is((select sum(e.delta) from inventory_entries e join inventory_items i on i.id=e.item_id where i.code='PIANO-TEST'),1::numeric,'One canonical quantity');
select throws_ok($$select receive_instrument('de920000-0000-4000-8000-000000000022',item_id,'SERIAL-1','de920000-0000-4000-8000-000000000011','Synthetic supplier',100,150,'VND','Duplicate') from instrument_catalogue c join inventory_items i on i.id=c.item_id where i.code='PIANO-TEST'$$,'23505',null,'Duplicate serial rejected');
select throws_ok($$select post_inventory_movement('de920000-0000-4000-8000-000000000023',id,'de920000-0000-4000-8000-000000000011','OUTBOUND',1,'Bypass') from inventory_items where code='PIANO-TEST'$$,'P0001','Serialized stock requires instrument workflow','Generic outbound cannot bypass serial evidence');
select throws_ok($$select post_inventory_movement('de920000-0000-4000-8000-000000000024',id,'de920000-0000-4000-8000-000000000011','ADJUSTMENT',1,'Bypass') from inventory_items where code='PIANO-TEST'$$,'P0001','Serialized stock requires instrument workflow','Generic adjustment cannot fabricate serial stock');
select lives_ok($$select move_instrument('de920000-0000-4000-8000-000000000025',id,'TRANSFER','de920000-0000-4000-8000-000000000012',null,null,null,'Transfer') from instrument_units where serial='SERIAL-1'$$,'Transfer unit');
select is((select sum(delta) from inventory_entries where movement_id='de920000-0000-4000-8000-000000000025'),0::numeric,'Same ledger paired transfer nets zero');
select lives_ok($$select move_instrument('de920000-0000-4000-8000-000000000026',id,'SALE',null,140,'VND',null,'Stock sale evidence only') from instrument_units where serial='SERIAL-1'$$,'Sale records price and stock disposal');
select lives_ok($$select move_instrument('de920000-0000-4000-8000-000000000026',id,'SALE',null,140,'VND',null,'Stock sale evidence only') from instrument_units where serial='SERIAL-1'$$,'Sale retry idempotent');
select is((select sum(e.delta) from inventory_entries e join inventory_items i on i.id=e.item_id where i.code='PIANO-TEST'),0::numeric,'Sold unit no longer in stock');
select is((select branch_id from instrument_events where movement_id='de920000-0000-4000-8000-000000000026'),'de920000-0000-4000-8000-000000000012'::uuid,'Sale uses actual transferred location');
select throws_ok($$select move_instrument('de920000-0000-4000-8000-000000000026',id,'SALE',null,141,'VND',null,'Stock sale evidence only') from instrument_units where serial='SERIAL-1'$$,'P0001','Inventory request payload mismatch','Cannot change sale through retry');
select throws_ok($$select move_instrument('de920000-0000-4000-8000-000000000027',id,'SALE',null,140,'VND',null,'Double sale') from instrument_units where serial='SERIAL-1'$$,'P0001','Instrument is not in stock','Second sale denied');
select throws_ok($$update instrument_commercial_details set acquisition_cost=0$$,'42501',null,'Cannot rewrite cost');
select throws_ok($$delete from instrument_events$$,'42501',null,'Cannot erase serial history');
select set_config('request.jwt.claim.sub','de920000-0000-4000-8000-000000000002',true);
select is((select count(*) from instrument_commercial_details),0::bigint,'Student cannot read cost');
select is((select count(*) from instrument_events),0::bigint,'Student cannot read sales');
select throws_ok($$select create_instrument_model('BAD','Bad','Test','Test','Test')$$,'P0001','Unauthorized','Student cannot manage models');
select throws_ok($$select receive_instrument(gen_random_uuid(),gen_random_uuid(),'BAD','de920000-0000-4000-8000-000000000011','Supplier',1,1,'VND','Bad')$$,'P0001','Unauthorized','Student cannot receive');
reset role;
select set_config('request.jwt.claim.sub','de920000-0000-4000-8000-000000000001',true);
update profiles set status='INACTIVE' where id='de920000-0000-4000-8000-000000000001';
set local role authenticated;
select is((select count(*) from instrument_commercial_details),0::bigint,'Inactive admin cannot read cost');
select throws_ok($$select move_instrument(gen_random_uuid(),gen_random_uuid(),'SALE',null,1,'VND',null,'Bad')$$,'P0001','Unauthorized','Inactive admin denied');
select ok(not has_function_privilege('anon','public.move_instrument(uuid,uuid,text,uuid,numeric,text,date,text)','EXECUTE'),'Anonymous execution denied');
select ok(not has_table_privilege('service_role','public.instrument_events','INSERT'),'Service cannot bypass instrument workflow');
select * from finish();
rollback;
